 {auto state=live;state.actor=2;state.party={1};state.worldFlags[c.facts.switches.at(552)]=false;GameSession member(c.items,state,c.facts);const auto* page=c.activeVariant(c.objects.at("m195-e9"),member);need(page&&page->page==2,"Active actor replaced actor-in-party predicate");}
