 SaveFiles files(c,root/"strict");need(files.write(1,disk).outcome==WriteOutcome::Committed,"Rule original disk failed");GameApplication active(c,"title",safe);std::string error;need(active.restore(disk,error),"Actual control restore failed");const auto held=active.session().exportState();const auto generation=active.generation();const auto original=read(root/"strict/slot-01.json");
 for(int mode:{0,1,2,3}){auto bad=Json::parse(encodeSave(c,disk));if(mode==0){bad["content"]="unknown";}if(mode==1){bad["session"]["hp"]="bad";}if(mode==2){bad["scene"]["map"]=195;}if(mode==3){for(auto& pair:bad["session"]["world_flags"]){if(pair[0]=="tower.dora-defeated"){pair[1]=false;}}}std::ofstream(root/"strict/slot-02.json")<<bad.dump();rejected=false;try{files.read(2);}catch(const std::exception&){rejected=true;}need(rejected&&active.generation()==generation&&active.session().exportState()==held&&read(root/"strict/slot-01.json")==original,"Bad save mutated old disk or active game");}
 // Existing FileMenu recovery reports Saved only for this exact committed candidate.
