 {SaveFiles failed(c,root/"failed",[](std::string_view stage){if(stage=="begin"){throw std::runtime_error("injected disk failure");}});SaveController controller(c,session,scene,failed,request,disk.presentation);for(int n=0;n<200;++n){controller.update({});}controller.update(key());controller.update(key());controller.update(key(InputAction::Cancel));controller.update(key(InputAction::Cancel));need(controller.finished()&&session.saveCount()==live.saveCount&&session.variable(399)==live.variables.at(399),"Failed save advanced count");}
 {GameSession stale(c.items,live,c.facts);CombatScene retired(c,stale,entry,safe);SaveFiles isolated(c,root/"stale");SaveController controller(c,stale,retired,isolated,{retired.generation(),"m196-e2","研究所　控制室"},disk.presentation);retired.deactivate();const auto stopped=stale.exportState();for(int n=0;n<300;++n){controller.update(key());}need(controller.finished()&&stale.exportState()==stopped&&isolated.list()[0].state==SlotState::Empty,"Old scene save completion committed");}
 std::ofstream(root/"rules.json")<<Json{{"kind","isolated-representative-rules-from-real-Save61; not natural proof"},{"claim_capacity_cases",30},{"both_map_sizes",true},{"door_failure_retry_cases",4},{"future_source_pages",true},{"recovery_current_old_unresolved",true},{"bad_source_preserves_active_and_disk",true},{"save_failure_and_stale_scene",true},{"cases",cases}}.dump(2)<<'\n';std::cout<<"03 representative rules/save-domain/recovery PASS cases="<<cases<<'\n';
